<template>
  <section v-loading="loading" class="automatic-flow">
    <div class="flow-heading"><div><strong>自动流程 · {{ stateName }}</strong><el-tag v-if="task.node" size="mini" :type="tone">{{ nodes[task.node]||task.node }}</el-tag><p>{{ task.last_message||'此单未纳入自动流程，可按当前业务条件人工处理。' }}</p></div><div><el-button v-if="task.state" v-hasPermi="['order:exchange:execute']" size="small" :loading="busy" @click="recheck">重新评估当前节点</el-button><el-button v-hasPermi="['order:exchange:config']" size="small" @click="settings">本店铺换货规则</el-button></div></div>
    <p v-if="task.state" class="hint">规则版本 {{ task.policy_revision }} · {{ task.next_attempt?'下次检查 '+task.next_attempt:'等待业务条件或人工核对' }} · {{ task.last_code }}</p>
    <el-button v-if="task.state==='MANUAL'||task.state==='HELD'" type="text" @click="$emit('locate',targetTab)">查看{{ nodes[task.node]||'当前节点' }}明细并处理</el-button>
    <el-collapse v-if="operations.length"><el-collapse-item :title="'平台自动操作记录（'+operations.length+'）'"><el-table :data="operations" size="small"><el-table-column label="动作" width="150"><template slot-scope="s">{{ actions[s.row.action]||s.row.action }} · 第{{ s.row.round_no }}轮</template></el-table-column><el-table-column label="结果" width="130"><template slot-scope="s">{{ operationStates[s.row.state]||s.row.state }}</template></el-table-column><el-table-column prop="message" label="交互说明" min-width="250" /><el-table-column prop="request_id" label="原请求号" min-width="220" /><el-table-column prop="create_time" label="登记时间" width="170" /></el-table></el-collapse-item></el-collapse>
  </section>
</template>
<script>
import {exchangeAutomaticFlow,exchangeAutomaticRecheck} from '@/api/order/exchange'
export default {
  props:{exchange:{type:Object,required:true}},data:()=>({loading:false,busy:false,task:{},operations:[],sequence:0,nodes:{REVIEW:'自动审核',POLICY:'店铺规则',SOURCE:'原单与商品来源',CONTROL:'挂起与截单',STOP:'平台撤回处理',STOCK:'换出库存',REFUND:'关联退款处理',AGREE:'平台同意',PLATFORM:'平台交互',RETURN:'退回实收',RETURN_DISPATCH:'退回仓库下发',COLLECT:'共同退回归集',QC:'退回验收',RECEIVED:'平台确认收货',ALLOCATION:'换出分仓',CARRIER:'快递匹配',DISPATCH:'仓库下发',SHIPMENT:'实际出库',CONSIGN:'运单回传',PLATFORM_CONFIRMATION:'平台最终确认',FINISHED:'完成',CONTINUE_REVIEW:'继续换出审核'},actions:{AGREE:'同意换货',RECEIVED:'确认收货',CONSIGN:'回传运单'},operationStates:{PENDING:'待执行',SENDING:'请求已发送',UNKNOWN:'结果未知·查原请求',SUCCESS:'已确认成功',FAILED:'已明确失败',CLOSED:'原请求已关闭'}}),
  computed:{stateName(){return ({PENDING:'待自动处理',WAITING:'等待下一节点',MANUAL:'需要人工核对',HELD:'已暂停',DONE:'处理完成'})[this.task.state]||'本单人工处理'},tone(){return this.task.state==='DONE'?'success':['MANUAL','HELD'].includes(this.task.state)?'warning':'info'},targetTab(){if(['RETURN','RETURN_DISPATCH','COLLECT','QC','RECEIVED'].includes(this.task.node))return 'returns';if(['REPLACEMENT','ALLOCATION','CARRIER','DISPATCH','SHIPMENT','CONSIGN','CONTINUE_REVIEW'].includes(this.task.node))return 'shipments';return 'overview'}},
  watch:{'exchange.id':{immediate:true,handler(){this.load()}},'exchange.control_version'(){this.load()}},beforeDestroy(){this.sequence++},methods:{async load(){const seq=++this.sequence;this.loading=true;try{const result=(await exchangeAutomaticFlow(this.exchange.id)).data;if(seq===this.sequence){this.task=result.task||{};this.operations=result.operations||[]}}finally{if(seq===this.sequence)this.loading=false}},async recheck(){if(this.busy)return;this.busy=true;try{await exchangeAutomaticRecheck(this.exchange.id,{control_version:this.exchange.control_version});await this.load();this.$message.success('已登记重新评估；仍按当前授权和实际执行结果校验')}finally{this.busy=false}},settings(){this.$router.push({path:'/oms-order/businessSettings',query:{channelId:String(this.exchange.channel_id),section:'exchange',exchangeId:this.exchange.id}})}}
}
</script>
<style scoped>.automatic-flow{background:#f7faff;border:1px solid #dfe9f6;border-radius:6px;padding:18px 22px;margin:18px 0}.flow-heading{display:flex;justify-content:space-between;gap:16px}.flow-heading p{margin-bottom:0;font-size:13px;line-height:1.8;color:#526b87}.el-tag{margin-left:12px}.hint{font-size:12px;color:#8190a5;line-height:1.8}.el-collapse{border:0;margin-top:12px}</style>
